messages.content:
 1	method SumOfSquaresOfFirstNOddNumbers(n: int) returns (sum: int)
 2	    requires n >= -1
 3	    ensures sum == (n * (2 * n - 1) * (2 * n + 1)) / 3
 4	{
 5	    sum := 0;
 6	    var i := 1;
 7	    for k:=0 to n
 8	        invariant 0 <= k <= n
 9	        invariant sum == k * (2 * k - 1) * (2 * k + 1) / 3
10	        invariant i == 2 * k + 1
11	    {
12	        sum := sum + i * i;
13	        i := i + 2;
14	    }
15	}

